98	     * the sheet's today; a to-date before the from-date is refused. */
99	    @Transactional
100	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
101	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
102	        LocalDate start = from == null ? sheet.getToday() : from;
103	        LocalDate end = to == null ? sheet.getToday() : to;
104	        if (end.isBefore(start)) {
105	            throw new PeriodRefusedException("to before from");
106	        }
107	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
108	        List<Period> made = new ArrayList<>();
109	        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
110	            String name = month.toString();
111	            LocalDate first = month.atDay(1);
112	            LocalDate last = month.atEndOfMonth();
113	            String key = Period.keyOf(name);
114	            if (existing.stream().anyMatch(p -> Period.keyOf(p.getName()).equals(key) || p.overlaps(first, last))) {
115	                continue;
116	            }
117	            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
118	            audit.change("PERIOD_ADDED", sheetId, user, "period=" + period.getName(), "from=" + period.getFrom(),
119	                    "to=" + period.getTo());
120	            existing.add(period);
121	            made.add(period);
122	        }
123	        return made;
124	    }
125	
126	    /** Make the twelve monthly periods of the fiscal year FY{@code year}, the one whose first day is the
127	     * first of the sheet's fiscal start month in {@code year}, exactly as {@link #generate} would. */
128	    @Transactional
129	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
130	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
131	        YearMonth first = YearMonth.of(year, sheet.getFiscalStartMonth());
132	        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
133	    }
134	
135	    /** Roll the fiscal year FY{@code year} over: make the next fiscal year's twelve monthly periods as
136	     * {@link #generateFiscalYear} would, then add each person's open figure at the end of the old year's last
137	     * period (see {@link #personOpenOf}) to their opening balance for the new year's first period, and
138	     * record it; the periods made. Refused when the user is not a steward or no period's from-date falls
139	     * in the old year. */
140	    @Transactional
141	    public List<Period> rollover(String sheetId, String user, int year) {
142	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
143	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
144	            throw new PeriodNotStewardException();
145	        }
146	        YearMonth start = YearMonth.of(year, sheet.getFiscalStartMonth());
147	        LocalDate oldFirst = start.atDay(1);
148	        LocalDate oldLast = start.plusMonths(11).atEndOfMonth();
149	        List<Period> old = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
150	                .filter(p -> !p.getFrom().isBefore(oldFirst) && !p.getFrom().isAfter(oldLast)).toList();
151	        if (old.isEmpty()) {
152	            throw new PeriodRefusedException("no periods");
153	        }
154	        Map<Long, BigDecimal> open = personOpenOf(sheetId, old);
155	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
156	        LocalDate newFirst = start.plusMonths(12).atDay(1);
157	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
158	                .filter(p -> p.overlaps(newFirst, newFirst)).findFirst()
159	                .ifPresent(first -> {
160	                    Period locked = periods.lockByIdAndSheetId(first.getId(), sheetId)
161	                            .orElseThrow(PeriodNotFoundException::new);
162	                    for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
163	                        BigDecimal amount = open.get(person.getId());
164	                        if (amount == null || amount.signum() == 0) continue;
165	                        locked.addOpening(person.getId(), amount);
166	                        audit.change("OPENING_SET", sheetId, user, "name=" + person.getName(),
167	                                "period=" + locked.getName(), "amount=" + amount.toPlainString());
168	                    }
169	                    periods.flush();
170	                });
171	        audit.change("ROLLOVER", sheetId, user, "fy=FY" + year, "periods=" + made.size());
172	        return made;
173	    }
174	
175	    /** Each person's open figure at the end of the last of {@code old}, by person id: the sum of what is
176	     * due on their claims whose due-by falls in one of {@code old} and that were OPEN or PENDING at the end
177	     * of its last day (see {@link #statusAt}), as each shows it now, counted as {@link #personCarriedOf} counts. */
178	    private Map<Long, BigDecimal> personOpenOf(String sheetId, List<Period> old) {
179	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
180	                .collect(Collectors.toMap(Person::getId, Function.identity()));
181	        Map<Long, BigDecimal> open = new HashMap<>();
182	        LocalDate end = old.stream().map(Period::getTo).max(Comparator.naturalOrder()).orElseThrow();
183	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
184	        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
185	        List<Claim> in = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
186	                .filter(claim -> claim.getDueBy() != null)
187	                .filter(claim -> all.stream().filter(p -> p.overlaps(claim.getDueBy(), claim.getDueBy())).findFirst()
188	                        .map(own -> old.stream().anyMatch(p -> p.getId().equals(own.getId()))).orElse(false))
189	                .toList();
190	        Map<Long, List<ClaimLog>> logsOf = in.isEmpty() ? Map.of()
191	                : logs.findByClaimIdInOrderByIdAsc(in.stream().map(Claim::getId).toList()).stream()
192	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
193	        for (Claim claim : in) {
194	            Person person = byId.get(claim.getPersonId());
195	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), end);
196	            if (person == null || status == null || !status.isOpen()) continue;
197	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
198	            if (!counts) continue;
199	            BigDecimal figure = rollup.shownOf(claim, person);
200	            if (figure != null) open.merge(person.getId(), figure, BigDecimal::add);
201	        }
202	        return open;
203	    }
204	
205	    /** Make the four calendar quarters of {@code year}, named yyyy-Q1 to yyyy-Q4, in order, each as
206	     * {@link #add} would add it; a quarter whose name is already a period's or whose days overlap a
207	     * period on the sheet is left out. */
208	    @Transactional
209	    public List<Period> generateQuarters(String sheetId, String user, int year) {
210	        if (!sheets.existsById(sheetId)) {
211	            throw new SheetNotFoundException();
212	        }
213	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
214	        List<Period> made = new ArrayList<>();
215	        for (int quarter = 1; quarter <= 4; quarter++) {
216	            String name = year + "-Q" + quarter;
217	            LocalDate first = YearMonth.of(year, quarter * 3 - 2).atDay(1);
218	            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
219	            String key = Period.keyOf(name);
220	            if (existing.stream().anyMatch(p -> Period.keyOf(p.getName()).equals(key) || p.overlaps(first, last))) {
221	                continue;
222	            }
223	            Period period = add(sheetId, user, name, first, last);
224	            existing.add(period);
225	            made.add(period);
226	        }
227	        return made;
228	    }
229	
230	    /** Close the period, fixing its due-total and each person's carried figure into it now (afresh when it was soft-closed); refused when the
231	     * user's role may not close (see {@link SettingsService#allowed}) or it is already closed, not
232	     * only soft-closed. */
233	    @Transactional
234	    public Period close(String sheetId, String user, long periodId) {
235	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
236	        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
237	            throw new PeriodNotStewardException();
238	        }
239	        if (period.isClosed() && !period.isSoft()) {
240	            throw new PeriodRefusedException("already closed");
241	        }
242	        return close(period, user);
243	    }
244	
245	    /** Soft-close the period, fixing its due-total now while claims dated in it can still change;
246	     * refused as {@link #close(String, String, long)} is, and when it is already closed or soft-closed. */
247	    @Transactional
248	    public Period softClose(String sheetId, String user, long periodId) {
249	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
250	        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
251	            throw new PeriodNotStewardException();
252	        }
253	        if (period.isClosed()) {
254	            throw new PeriodRefusedException("already closed");
255	        }
256	        period.close(personTotalsOf(period), personCarriedOf(period), true);
257	        periods.flush();
258	        audit.change("PERIOD_SOFT_CLOSED", sheetId, user, "period=" + period.getName(),
259	                "total=" + period.getClosedTotal().toPlainString());
260	        return period;
261	    }
262	
263	    /** Close, as {@link #close(String, String, long)} would, every open period of the sheet whose to-date
264	     * plus its grace days is before its today, in order of their to-dates, each marked auto=yes; nothing
265	     * when the grace days are off. An automatic close is not subject to the permission matrix. */
266	    @Transactional
267	    public void closeOverdue(String sheetId, String user) {
268	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
269	        Integer grace = sheet.getGraceDays();
270	        if (grace == null) return;
271	        List<Period> due = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
272	                .filter(p -> !p.isClosed() && p.getTo().plusDays(grace).isBefore(sheet.getToday()))
273	                .sorted(Comparator.comparing(Period::getTo)).toList();
274	        for (Period open : due) {
275	            Period period = periods.lockByIdAndSheetId(open.getId(), sheetId).orElseThrow(PeriodNotFoundException::new);
276	            if (!period.isClosed()) close(period, user, "auto=yes");
277	        }
278	    }
279	
280	    private Period close(Period period, String user, String... extra) {
281	        period.close(personTotalsOf(period), personCarriedOf(period));
282	        periods.flush();
283	        List<String> fields = new ArrayList<>(List.of("period=" + period.getName(),
284	                "total=" + period.getClosedTotal().toPlainString()));
285	        fields.addAll(List.of(extra));
286	        audit.change("PERIOD_CLOSED", period.getSheetId(), user, fields.toArray(String[]::new));
287	        return period;
288	    }
289	
290	    /** Reopen the period, making its due-total and the carried figures into it live again; refused when the user's role may not
291	     * reopen (a steward's by default, see {@link SettingsService#allowed}) or the period is not closed
292	     * or soft-closed, or it is locked. */
293	    @Transactional
294	    public Period reopen(String sheetId, String user, long periodId) {
295	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
296	        if (!settings.allowed(sheetId, user, Action.REOPEN)) {
297	            throw new PeriodNotStewardException();
298	        }
299	        if (!period.isClosed()) {
300	            throw new PeriodRefusedException("not closed");
301	        }
302	        if (period.isLocked()) {
303	            throw new PeriodRefusedException("locked");
304	        }
305	        period.reopen();
306	        periods.flush();
307	        audit.change("PERIOD_REOPENED", sheetId, user, "period=" + period.getName());
308	        return period;
309	    }
310	
311	    /** Lock the period, so it cannot be reopened; refused when the user is not a steward or it is already locked. */
312	    @Transactional
313	    public Period lock(String sheetId, String user, long periodId) {
314	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
315	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
316	            throw new PeriodNotStewardException();
317	        }
318	        if (period.isLocked()) {
319	            throw new PeriodRefusedException("already locked");
320	        }
321	        period.setLocked(true);
322	        periods.flush();
323	        audit.change("PERIOD_LOCKED", sheetId, user, "period=" + period.getName());
324	        return period;
325	    }
326	
327	    /** Unlock the period; refused when the user is not a steward or it is not locked. */
328	    @Transactional
329	    public Period unlock(String sheetId, String user, long periodId) {
330	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
331	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
332	            throw new PeriodNotStewardException();
333	        }
334	        if (!period.isLocked()) {
335	            throw new PeriodRefusedException("not locked");
336	        }
337	        period.setLocked(false);
338	        periods.flush();
339	        audit.change("PERIOD_UNLOCKED", sheetId, user, "period=" + period.getName());
340	        return period;
341	    }
342	
343	    /** Each person's due-total for the period now, by person id, for everyone on the sheet: the sum of
344	     * what is due on their claims whose due-by falls in it that counted by the status each had at the end of the
345	     * period's last day (see {@link #statusAt}), as each shows it now, late charges included (a
346	     * claim with no figure adds nothing, nor does an OPEN claim deferred on the sheet's today, while the claim is still OPEN or PENDING now). */
347	    private Map<Long, BigDecimal> personTotalsOf(Period period) {
348	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(period.getSheetId()).stream()
349	                .collect(Collectors.toMap(Person::getId, Function.identity()));
350	        Map<Long, BigDecimal> totals = new HashMap<>();
351	        for (Long id : byId.keySet()) totals.put(id, BigDecimal.ZERO.setScale(2));
352	        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
353	        List<Claim> dated = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
354	                .filter(claim -> period.overlaps(claim.getDueBy(), claim.getDueBy())).toList();
355	        Map<Long, List<ClaimLog>> logsOf = dated.isEmpty() ? Map.of()
356	                : logs.findByClaimIdInOrderByIdAsc(dated.stream().map(Claim::getId).toList()).stream()
357	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
358	        for (Claim claim : dated) {
359	            Person person = byId.get(claim.getPersonId());
360	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
361	            if (person == null || status == null) continue;
362	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
363	            if (!counts) continue;
364	            BigDecimal figure = rollup.shownOf(claim, person);
365	            if (figure != null) totals.merge(person.getId(), figure, BigDecimal::add);
366	        }
367	        return totals;
368	    }
369	
370	    /** Each person's carried figure into the period now, by person id, for everyone on the sheet: the sum
371	     * of what is due on their claims whose due-by falls in a period of the sheet ending before this one
372	     * starts and that were still OPEN or PENDING at the end of this one's last day (see {@link #statusAt}),
373	     * and their opening balance for it,
374	     * as each shows it now (a claim with no figure adds nothing, nor does one that would not count then,
375	     * as {@link #personTotalsOf} counts). */
376	    private Map<Long, BigDecimal> personCarriedOf(Period period) {
377	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(period.getSheetId()).stream()
378	                .collect(Collectors.toMap(Person::getId, Function.identity()));
379	        Map<Long, BigDecimal> carried = new HashMap<>();
380	        for (Long id : byId.keySet()) carried.put(id, BigDecimal.ZERO.setScale(2));
381	        period.getPersonOpenings().forEach((id, opening) -> {
382	            if (byId.containsKey(id)) carried.merge(id, opening, BigDecimal::add);
383	        });
384	        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
385	        List<Period> all = periods.findBySheetIdOrderByFromAsc(period.getSheetId());
386	        if (all.stream().noneMatch(p -> p.getTo().isBefore(period.getFrom()))) return carried;
387	        List<Claim> before = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
388	                .filter(claim -> claim.getDueBy() != null)
389	                .filter(claim -> all.stream().filter(p -> p.overlaps(claim.getDueBy(), claim.getDueBy())).findFirst()
390	                        .map(own -> own.getTo().isBefore(period.getFrom())).orElse(false))
391	                .toList();
392	        Map<Long, List<ClaimLog>> logsOf = before.isEmpty() ? Map.of()
393	                : logs.findByClaimIdInOrderByIdAsc(before.stream().map(Claim::getId).toList()).stream()
394	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
395	        for (Claim claim : before) {
396	            Person person = byId.get(claim.getPersonId());
397	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
398	            if (person == null || status == null || !status.isOpen()) continue;
399	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
400	            if (!counts) continue;
401	            BigDecimal figure = rollup.shownOf(claim, person);
402	            if (figure != null) carried.merge(person.getId(), figure, BigDecimal::add);
403	        }
404	        return carried;
405	    }
406	
407	    /** The status a claim had at the end of {@code day}, by its status log, oldest first, whose lines
408	     * are dated with the sheet's today when each change was made; null when it was added after. */
409	    private static ClaimStatus statusAt(List<ClaimLog> log, LocalDate day) {
410	        ClaimStatus status = null;
411	        for (ClaimLog line : log) {
412	            if (line.getDate().isAfter(day)) break;
413	            status = line.getStatus();
414	        }
415	        return status;
416	    }
417	}
